const { execFileSync } = await import('node:child_process');
execFileSync('npm', ['--prefix', 'packages/main', 'run', 'build'], { cwd: $root, encoding: 'utf8' });
execFileSync('npm', ['--prefix', 'packages/utils', 'run', 'build'], { cwd: $root, encoding: 'utf8' });
const docs = execFileSync('node', ['bin/koala.js', 'aux_doc_list', '--format=json'], { cwd: $root, encoding: 'utf8' });
const brief = execFileSync('node', ['bin/koala-codex.js', 'session_brief'], { cwd: $root, encoding: 'utf8' });
return { docsOk: docs.includes('"docs"'), briefOk: brief.includes('# koala session brief') };

const { execFileSync } = await import('node:child_process');
const { renameSync, existsSync } = await import('node:fs');
const { join } = await import('node:path');
const dist = join($root, 'packages', 'utils', 'dist');
const backup = join($root, 'packages', 'utils', 'dist.__bak__');
if (!existsSync(dist)) throw new Error('utils dist missing before test');
renameSync(dist, backup);
try {
  execFileSync('node', ['bin/koala.js', 'help'], { cwd: $root, encoding: 'utf8', stdio: 'pipe' });
  return { recovered: false, hasMissing: false };
} catch (error) {
  const text = String(error.stderr || error.stdout || error.message || error);
  return { recovered: text.includes('Recovery:'), hasMissing: text.includes('Missing build artifacts:'), mentionsUtilsBuild: text.includes('npm --prefix packages/utils run build') };
} finally { renameSync(backup, dist); }

const { execFileSync } = await import("node:child_process");
const { mkdirSync, writeFileSync, rmSync, existsSync } = await import("node:fs");
const { join } = await import("node:path");
const altZodDir = join($root, "node_modules", "zod");
mkdirSync(altZodDir, { recursive: true });
writeFileSync(join(altZodDir, "package.json"), JSON.stringify({ name: "zod", version: "0.0.0-test", type: "module", exports: "./index.js" }));
writeFileSync(join(altZodDir, "index.js"), "throw new Error(\"root zod should not be imported\");\n");
try {
  const docs = execFileSync("node", ["bin/koala.js", "aux_doc_list", "--format=json"], { cwd: $root, encoding: "utf8" });
  return { secondInstancePresent: existsSync(join(altZodDir, "index.js")), docsOk: docs.includes("\"docs\""), noRootZodCrash: !docs.includes("root zod should not be imported") };
} finally {
  rmSync(join($root, "node_modules"), { recursive: true, force: true });
}

