const { execFileSync } = await import('node:child_process');
const { mkdtempSync, existsSync, rmSync, readFileSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const tempDir = mkdtempSync(join(tmpdir(), 'koala-entrypoints-case-'));
try {
  const out = execFileSync('node', ['packages/main/dist/cli.js', 'init', tempDir], { cwd: $root, encoding: 'utf8' });
  const codexReadme = readFileSync(join(tempDir, '.Codex', 'README.md'), 'utf8');
  return { outputMentionsCodexReadme: out.includes('.Codex/README.md'), hasAgents: existsSync(join(tempDir, '.Codex', 'agents', 'test-intent.md')), hasFallback: codexReadme.includes('KOALA_ACTIVITY_SOURCE=codex koala session_brief') };
} finally { rmSync(tempDir, { recursive: true, force: true }); }

